using Yubico.YubiKit.Core.Protocols.SmartCard.Apdu;
using Yubico.YubiKit.Core.Protocols.SmartCard.Scp;
using Yubico.YubiKit.Core.Sessions;
using Yubico.YubiKit.Tests.Shared;

namespace Yubico.YubiKit.Oath.IntegrationTests.TestExtensions;

/// <summary>
///     Extensions that help integration tests acquire <see cref="OathSession" />
///     instances while ensuring connections are disposed correctly.
/// </summary>
public static class OathTestStateExtensions
{
    extension(YubiKeyTestState state)
    {
        /// <summary>
        ///     Executes an action with an OATH session.
        ///     Optionally resets the OATH application before running the action.
        /// </summary>
        /// <param name="action">The async action to execute with the session.</param>
        /// <param name="resetBeforeUse">
        ///     When <c>true</c>, resets the OATH application before running the test action.
        ///     Defaults to <c>true</c>.
        /// </param>
        /// <param name="configuration">Optional protocol configuration.</param>
        /// <param name="scpKeyParams">Optional SCP key parameters for secure channel.</param>
        /// <param name="cancellationToken">Cancellation token.</param>
        public async Task WithOathSessionAsync(
            Func<OathSession, Task> action,
            bool resetBeforeUse = true,
            ProtocolConfiguration? configuration = null,
            ScpKeyParameters? scpKeyParams = null,
            CancellationToken cancellationToken = default)
        {
            if (resetBeforeUse)
            {
                // RESET ends its session and owned connection. The test body must open afresh.
                var resetSession = await state.Device.CreateOathSessionAsync(
                    new SessionCreationOptions { ScpKeyParameters = scpKeyParams, ProtocolConfiguration = configuration },
                    cancellationToken).ConfigureAwait(false);
                await WithSessionLifetimeAsync(resetSession, session => session.ResetAsync(cancellationToken)).ConfigureAwait(false);
            }

            var session = await state.Device
                .CreateOathSessionAsync(
                    new SessionCreationOptions
                    {
                        ScpKeyParameters = scpKeyParams,
                        ProtocolConfiguration = configuration
                    },
                    cancellationToken)
                .ConfigureAwait(false);

            await WithSessionLifetimeAsync(session, action).ConfigureAwait(false);
        }
    }

    private static async Task WithSessionLifetimeAsync(OathSession session, Func<OathSession, Task> action)
    {
        Exception? primaryFailure = null;
        try { await action(session).ConfigureAwait(false); }
        catch (Exception exception)
        {
            primaryFailure = exception;
            throw;
        }
        finally
        {
            // RESET already disposes after success. Also close after a send/body failure,
            // without a second implicit owner replaying teardown over the original failure.
            try { await session.DisposeAsync().ConfigureAwait(false); }
            catch when (primaryFailure is not null) { }
        }
    }
}
